package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_conflict_declaration") public class ConflictDeclaration extends RspAuditedEntity{
 public enum Outcome{NO_CONFLICT,POTENTIAL_CONFLICT_REVIEW_REQUIRED,CONFLICT_RECUSED}public enum Resolution{CLEARED,RECUSED}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="candidate_id",length=36)private String candidateId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private Outcome outcome;@Column(nullable=false,length=2000)private String declaration;@Column(name="declared_at",nullable=false)private Instant declaredAt;@Enumerated(EnumType.STRING)@Column(name="resolved_outcome",length=30)private Resolution resolvedOutcome;@Column(name="resolved_by",length=100)private String resolvedBy;@Column(name="resolved_at")private Instant resolvedAt;@Column(name="resolution_reason",length=2000)private String resolutionReason;
 protected ConflictDeclaration(){}public ConflictDeclaration(String agency,String proceeding,String candidate,String employee,Outcome outcome,String declaration,Instant at){super(agency);proceedingId=requiredText(proceeding,"proceedingId");candidateId=optionalText(candidate);employeeNo=requiredText(employee,"employeeNo");this.outcome=Objects.requireNonNull(outcome);this.declaration=requiredText(declaration,"declaration");declaredAt=Objects.requireNonNull(at);}
 public void resolve(Resolution resolution,String actor,String reason,Instant at){if(outcome!=Outcome.POTENTIAL_CONFLICT_REVIEW_REQUIRED)throw new IllegalStateException("Only a potential conflict may be resolved");if(employeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("A member cannot resolve their own conflict");resolvedOutcome=Objects.requireNonNull(resolution);resolvedBy=requiredText(actor,"actor");resolutionReason=requiredText(reason,"reason");resolvedAt=Objects.requireNonNull(at);}
 public boolean blocksAction(){return outcome==Outcome.CONFLICT_RECUSED||outcome==Outcome.POTENTIAL_CONFLICT_REVIEW_REQUIRED&&(resolvedOutcome==null||resolvedOutcome==Resolution.RECUSED);}public String getProceedingId(){return proceedingId;}public String getCandidateId(){return candidateId;}public String getEmployeeNo(){return employeeNo;}public Outcome getOutcome(){return outcome;}public Resolution getResolvedOutcome(){return resolvedOutcome;}public String getDeclaration(){return declaration;}
}
